# The utilization chart's stacks: every asset when there are 12 or fewer; otherwise the 11 busiest (by time with data) and the rest together
data = dict(value) if value else {}
MAX = 12
assets = []
for a in (data.get('utilizationAssets') or []):
	mins = dict((dict(c)['category'], dict(c)['mins']) for c in a['categories'])
	assets.append({'name': a['label'], 'mins': mins, 'busy': sum(m for k, m in mins.items() if k != 'No data')})
assets.sort(key=lambda x: -x['busy'])
stacks = [{'name': x['name'], 'other': False, 'mins': x['mins']} for x in (assets if len(assets) <= MAX else assets[:MAX - 1])]
rest = assets[MAX - 1:] if len(assets) > MAX else []
if rest:
	mins = {}
	for x in rest:
		for k, m in x['mins'].items():
			mins[k] = mins.get(k, 0) + m
	stacks.append({'name': '%d other assets' % len(rest), 'other': True, 'mins': mins})
# 'No data' (no mode recorded) isn't plotted
return {'categories': [dict(c)['category'] for c in (data.get('utilizationTotal') or []) if dict(c)['category'] != 'No data'], 'stacks': stacks}

