# Read the losses, utilization and schedule delay of every OEE asset under the chosen one, in the background:
# system.kanoa.event.getReliabilityData does it in a few queries, whatever the number of assets
view = self.view
options = dict(view.custom.options)
def shortStopSecs(v):
	# The number input can hand back None, or the text 'None', when it's empty: use the default 300 s then
	try:
		return max(0, int(float(v)))
	except (TypeError, ValueError):
		return 300
start, end = options.get('startDate'), options.get('endDate')
if start is None or end is None or start >= end:
	system.kanoa.toast.show({'type': 'error', 'message': 'Choose a date range that ends after it starts'})
	return
params = {'assetPath': options.get('assetPath') or '', 'startDate': start, 'endDate': end,
		  'shortStopSecs': shortStopSecs(options.get('shortStop'))}
view.custom.status = {'busy': True}
view.custom.drill = {'family': None, 'bucket': None, 'assetPath': None}
# One toast for the whole read: a spinner now, the outcome when it's done (the background thread has no page, so it
# names this one)
target = {'sessionId': self.session.props.id, 'pageId': self.page.props.pageId}
tid = system.kanoa.toast.show(dict(target, message='Reading the loss data', loading=True))

def work():
	data = system.kanoa.event.getReliabilityData(params)
	view.custom.status = {'busy': False}
	if data is None:
		system.kanoa.toast.update(dict(target, id=tid, type='error', autoClose=0,
									   message="Couldn't read the loss data: see the gateway log"))
		return
	view.custom.summary = data
	if not data['assets']:
		system.kanoa.toast.update(dict(target, id=tid, type='warning', message='No OEE assets under ' + (params['assetPath'] or 'the enterprise')))
	else:
		# What the report was built from: the assets and their production runs in the range
		def count(n, thing):
			return '{:,} {}{}'.format(int(n), thing, '' if n == 1 else 's')
		system.kanoa.toast.update(dict(target, id=tid, type='success', message='Analyzed %s and %s' % (
			count(data['assets'], 'asset'), count(data.get('productionRuns') or 0, 'production run'))))

system.util.invokeAsynchronous(work)

# The loss families and their buckets, in the order they come off planned run time
FAMILIES = [
	('AVAILABILITY', 'Availability', 'var(--kcRed-60)', [('UNPLANNED', 'Unplanned downtime')]),
	('PERFORMANCE', 'Performance', 'var(--kcOrange-60)', [('MINOR_STOP', 'Minor stops'), ('SPEED_LOSS', 'Speed loss')]),
	('QUALITY', 'Quality', 'var(--kcPurple-60)', [('QUALITY_LOSS', 'Quality loss')]),
]
# The drill-down lists for the selection, from the data: the losses (all, or one family's), the assets losing most to
# the selected loss, its top reasons; its events are read for the selection in the background
view = self.view
data = dict(view.custom.summary) if view.custom.summary else {}
if not data.get('assets'):
	view.custom.lists = {'losses': [], 'assets': [], 'reasons': [], 'events': []}
	return
drill = view.custom.drill
family, bucket, assetPath = drill.family, drill.bucket, drill.assetPath
colorOf = dict((b[0], f[2]) for f in FAMILIES for b in f[3])
familyOf = dict((b[0], f[0]) for f in FAMILIES for b in f[3])
color = colorOf.get(bucket) or dict((f[0], f[2]) for f in FAMILIES).get(family) or 'var(--kcBlue-60)'

def bars(level, rows, selectedKey, countLabel=None):
	rows = sorted([r for r in rows if r['mins'] > 0], key=lambda r: -r['mins'])
	top = rows[0]['mins'] if rows else 0
	whole = sum(r['mins'] for r in rows) or 1.0
	for r in rows:
		r.update({'level': level, 'maxMins': top, 'pct': 100.0 * r['mins'] / whole, 'selected': r['key'] == selectedKey})
		if countLabel: r['countLabel'] = countLabel
	return rows

inFamily = lambda b: family is None or familyOf.get(b) == family
losses = bars('bucket', [{'key': r['bucket'], 'label': r['label'], 'mins': r['mins'], 'count': r['count'], 'countLabel': r['countLabel'],
						  'color': colorOf.get(r['bucket'])} for r in data['buckets'] if inFamily(r['bucket'])], bucket)

keys = [bucket] if bucket else [b for b in familyOf if inFamily(b)]
byAsset = {}
for r in data['bucketAssets']:
	if r['bucket'] in keys:
		row = byAsset.setdefault(r['assetPath'], {'key': r['assetPath'], 'label': r['label'], 'mins': 0.0, 'count': 0, 'color': color})
		row['mins'] += r['mins']
		row['count'] += r['count']
assets = bars('asset', byAsset.values(), assetPath, 'events')

reasons = []
if bucket:
	byReason = {}
	for r in data['bucketReasons']:
		if r['bucket'] == bucket and (assetPath is None or r['assetPath'] == assetPath):
			row = byReason.setdefault(r['reason'], {'key': r['reason'], 'label': r['reason'], 'mins': 0.0, 'count': 0, 'color': color})
			row['mins'] += r['mins']
			row['count'] += r['count']
	reasons = bars('reason', byReason.values(), None, 'runs' if bucket in ('SPEED_LOSS', 'QUALITY_LOSS') else 'stops')[:15]
view.custom.lists = {'losses': losses, 'assets': assets, 'reasons': reasons, 'events': []}

if bucket:
	options = dict(view.custom.options)
	def shortStopSecs(v):
		# The number input can hand back None, or the text 'None', when it's empty: use the default 300 s then
		try:
			return max(0, int(float(v)))
		except (TypeError, ValueError):
			return 300
	params = {'assetPath': options.get('assetPath') or '', 'startDate': options.get('startDate'), 'endDate': options.get('endDate'),
			  'shortStopSecs': shortStopSecs(options.get('shortStop')),
			  'bucket': bucket, 'eventAssetPath': assetPath}
	def events():
		data = system.kanoa.event.getReliabilityEvents(params)
		if data is not None and view.custom.drill.bucket == bucket:
			view.custom.lists.events = data
	system.util.invokeAsynchronous(events)

